use rstsr::prelude::*;

use super::CATEGORY;
use crate::TESTCFG;

mod doc_norm {
    use super::*;
    static FUNC: &str = "doc_norm";

    #[test]
    fn test_doc() {
        crate::specify_test!("test_doc");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // 2-norm of a vector
        let v = rt::tensor_from_nested!([3.0, 4.0], &device);
        println!("{}", rt::norm(&v, 2.0));
        assert_eq!(rt::norm(&v, 2.0), 5.0);
        assert_eq!(format!("{}", rt::norm(&v, 2.0)), "5");

        // matrix norms on 2-D input, with the string ord spelling
        let a = rt::tensor_from_nested!([[1.0, 2.0], [3.0, 4.0]], &device);
        println!("{}", rt::norm(&a, "fro"));
        assert_eq!(rt::norm(&a, "fro"), 5.477225575051661);
        assert_eq!(format!("{}", rt::norm(&a, "fro")), "5.477225575051661");
        println!("{}", rt::norm(&a, 1.0));
        assert_eq!(rt::norm(&a, 1.0), 6.0);
        assert_eq!(format!("{}", rt::norm(&a, 1.0)), "6");

        // per-row maximum absolute value, keepdims
        let n = rt::norm_with_args(&a, f64::INFINITY, ([1], true));
        println!("{n}");
        assert_eq!(format!("{n}"), "[[ 2]\n [ 4]]");
    }
}
